import sys
from collections import deque

def xShape(grid):
    if not grid or not grid[0]:
        return 0

    n = len(grid)
    m = len(grid[0])
    visited = [[False for _ in range(m)] for _ in range(n)]

    def bfs(i, j):
        queue = deque([(i, j)])
        visited[i][j] = True
        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

        while queue:
            r, c = queue.popleft()
            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < m:
                    if not visited[nr][nc] and grid[nr][nc] == 'X':
                        visited[nr][nc] = True
                        queue.append((nr, nc))

    count = 0
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 'X' and not visited[i][j]:
                count += 1
                bfs(i, j)

    return count

